map(fn) { return new Plan(source, {previous: tail, kind: "map", fn}); }
filter(fn) { return new Plan(source, {previous: tail, kind: "filter", fn}); }
compile(tail) { const cells=[]; for (let c=tail; c; c=c.previous) cells.push(c); cells.reverse();
 const runs=[]; for (const c of cells) { const last=runs.at(-1);
  if (c.kind==="map" && last?.kind==="map") last.fns.push(c.fn); else runs.push({kind:c.kind, fns:[c.fn]}); }
 return runs.map(r => r.kind==="map" ? {kind:"map", call:composite(r.fns)} : {kind:"filter", call:r.fns[0]}); }
composite(fns) { return value => { for (const fn of fns) value=fn(value); return value; }; }
terminal(target, collect) { const stages=compile(tail); const output=[]; let ordinal=0;
 sourceLoop: for (const original of source) { let value=original;
  for (const s of stages) { if (s.kind==="filter") { if (!s.call(value)) continue sourceLoop; } else value=s.call(value); }
  if (!collect && Object.is(value,target)) return ordinal;
  if (collect) output.push(value); ordinal++;
 } return collect ? output : -1; }

append(kind, fn) { return new CursorFactory(source, {previous: tail, kind, fn}); }
open() { let layer=sourceIterator(source);                 // private per consumer
 for (const run of flattenToRuns(tail))                   // iterative; adjacent maps grouped
  layer = run.kind==="filter" ? new FilterIter(layer, run.fn) : new MapRunIter(layer, composite(run.fns));
 return guard(layer); }
FilterIter.next() { for(;;) { const n=this.up.next(); if (n.done || this.fn(n.value)) return n; } }
MapRunIter.next() { const n=this.up.next(); return n.done ? n : {done:false, value:this.run(n.value)}; }
Layer.close() { if (!this.closed) { this.closed=true; this.up.close(); } }
guard(top) { let closed=false; return {
 next() { if (closed) return {done:true};
  try { const n=top.next(); if (n.done) { closed=true; top.close(); } return n; }
  catch (e) { closed=true; top.close(); throw e; } },
 close() { if (!closed) { closed=true; top.close(); } } }; }
